const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artikler</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Den tyske artikkelen stemmer ikke alltid med kjønnet på ordet på norsk. Derfor er det best å lære substantiver sammen med artikkelen.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Eksempler på artikler</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — bord</div>\n      <div class=\"kurss-example\">die Tür — dør</div>\n      <div class=\"kurss-example\">das Messer — kniv</div>\n      <div class=\"kurss-example\">das Mädchen — jente</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Ofte DER</h4>\n    <p class=\"artikuli-explain\">DER brukes ofte om menn, dager, måneder, årstider og noen ord med bestemte endelser.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → ofte DER, for eksempel: der Computer, der Lehrer <span class=\"artikuli-note\">men ikke alltid</span></div>\n      <div class=\"kurss-example\">-ling → ofte DER, for eksempel: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → ofte DER, for eksempel: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">menn → der Mann, der Vater</div>\n      <div class=\"kurss-example\">yrker → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">bilmerker → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dager → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">måneder → der August, der Dezember</div>\n      <div class=\"kurss-example\">årstider → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Eksempler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — mann</div>\n      <div class=\"kurss-example\">der Vater — far</div>\n      <div class=\"kurss-example\">der Montag — mandag</div>\n      <div class=\"kurss-example\">der August — august</div>\n      <div class=\"kurss-example\">der Sommer — sommer</div>\n      <div class=\"kurss-example\">der Lehrer — lærer</div>\n      <div class=\"kurss-example\">der Computer — datamaskin</div>\n      <div class=\"kurss-example\">der Schmetterling — sommerfugl</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Ofte DIE</h4>\n    <p class=\"artikuli-explain\">DIE brukes ofte om kvinner, flertall og ord med endelsene -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">kvinner → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motorsykkelmerker → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">flertall → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">flertall nesten alltid → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Eksempler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — kvinne</div>\n      <div class=\"kurss-example\">die Mutter — mor</div>\n      <div class=\"kurss-example\">die Wohnung — leilighet</div>\n      <div class=\"kurss-example\">die Rechnung — regning</div>\n      <div class=\"kurss-example\">die Freiheit — frihet</div>\n      <div class=\"kurss-example\">die Möglichkeit — mulighet</div>\n      <div class=\"kurss-example\">die Mannschaft — lag</div>\n      <div class=\"kurss-example\">die Nation — nasjon</div>\n      <div class=\"kurss-example\">die Universität — universitet</div>\n      <div class=\"kurss-example\">die Polizei — politi</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Ofte DAS</h4>\n    <p class=\"artikuli-explain\">DAS brukes ofte om diminutiver med -chen / -lein, mange ord med -ment / -um og verb brukt som substantiv.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metaller → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">kjemiske grunnstoffer → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hoteller → das Hotel</div>\n      <div class=\"kurss-example\">farger som substantiv → das Rot, das Blau</div>\n      <div class=\"kurss-example\">verb som substantiv → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">verb som substantiv → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Eksempler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — barn</div>\n      <div class=\"kurss-example\">das Mädchen — jente</div>\n      <div class=\"kurss-example\">das Häuschen — lite hus</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — sentrum</div>\n      <div class=\"kurss-example\">das Museum — museum</div>\n      <div class=\"kurss-example\">das Essen — spising / mat</div>\n      <div class=\"kurss-example\">das Lernen — læring</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Viktige unntak / må læres med artikkel</h4>\n    <p class=\"artikuli-explain\">For noen ord kan man ikke sikkert avgjøre artikkelen ut fra endelsen eller det norske kjønnet. Disse er best å lære sammen med artikkelen.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — dør</div>\n      <div class=\"kurss-example\">das Messer — kniv</div>\n      <div class=\"kurss-example\">die Sonne — sol</div>\n      <div class=\"kurss-example\">der Mond — måne</div>\n      <div class=\"kurss-example\">das Mädchen — jente</div>\n      <div class=\"kurss-example\">das Auto — bil</div>\n      <div class=\"kurss-example\">der Käse — ost</div>\n      <div class=\"kurss-example\">die Gabel — gaffel</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Endelser og ordgrupper hjelper deg å gjette artikkelen, men de er ingen 100 % sikker regel. Hvis du er usikker, lær ordet sammen med artikkelen.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Pronomen</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ og Dativ — pronomenformer.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — hvem/hva?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — jeg</div><div class=\"kurss-example\">du — du</div><div class=\"kurss-example\">er — han</div><div class=\"kurss-example\">sie — hun</div><div class=\"kurss-example\">es — det</div><div class=\"kurss-example\">wir — vi</div><div class=\"kurss-example\">ihr — dere</div><div class=\"kurss-example\">sie — de</div><div class=\"kurss-example\">Sie — De (høflig)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — hvem/hva?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — meg</div><div class=\"kurss-example\">dich — deg</div><div class=\"kurss-example\">ihn — ham (m.)</div><div class=\"kurss-example\">sie — henne (f.)</div><div class=\"kurss-example\">es — det</div><div class=\"kurss-example\">uns — oss</div><div class=\"kurss-example\">euch — dere</div><div class=\"kurss-example\">sie — dem</div><div class=\"kurss-example\">Sie — Dem (høflig)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — til hvem?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — (til) meg</div><div class=\"kurss-example\">dir — (til) deg</div><div class=\"kurss-example\">ihm — (til) ham / det</div><div class=\"kurss-example\">ihr — (til) henne</div><div class=\"kurss-example\">uns — (til) oss</div><div class=\"kurss-example\">euch — (til) dere</div><div class=\"kurss-example\">ihnen — (til) dem</div><div class=\"kurss-example\">Ihnen — (til) Dem (høflig)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Hvordan velge riktig form?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — subjekt (hvem gjør noe?)</li><li><span class=\"case-red\">Akkusativ</span> — direkte objekt (hvem/hva?)</li><li><span class=\"case-green\">Dativ</span> — indirekte objekt (til hvem?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Eksempler</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Jeg ser deg.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Jeg ser ham.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Vi liker dere.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Jeg hjelper deg.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Jeg gir ham en bok.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Vi takker dere.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ er alltid subjektet i setningen, mens Akkusativ og Dativ er objekter. Se på verbet og spør: <span class=\"case-red\">hvem/hva?</span> eller <span class=\"case-green\">til hvem?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vokaler — lange og korte</h3>\n            <p class=\"kurss-lesson-intro\">På tysk kan vokaler være lange eller korte. Det påvirker hvordan ordet uttales.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Lang vokal</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — varm</div><div class=\"kurss-example\">gut (gōt) — god / bra</div><div class=\"kurss-example\">Tat (tāt) — handling / gjerning</div><div class=\"kurss-example\">Flur (flōr) — gang / entré</div><div class=\"kurss-example\">Weg (vēk) — vei</div><div class=\"kurss-example\">Hut (hōt) — hatt</div><div class=\"kurss-example\">Hof (hå̄f) — gård / gårdsplass</div><div class=\"kurss-example\">Schlaf (sjlāf) — søvn</div></div>\n              <p>Når det kommer én konsonant etter vokalen, uttales vokalen ofte lang.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kort vokal</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilts) — sopp</div><div class=\"kurss-example\">Wort (vårt) — ord</div><div class=\"kurss-example\">Mund (mont) — munn</div><div class=\"kurss-example\">bald (balt) — snart</div><div class=\"kurss-example\">scharf (sjarf) — skarp</div><div class=\"kurss-example\">Feld (felt) — felt / åker</div><div class=\"kurss-example\">voll (fåll) — full</div></div>\n              <p>Når det kommer to eller flere konsonanter etter vokalen, uttales vokalen ofte kort.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Endelsene en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zingen) — synge</div><div class=\"kurss-example\">tragen (trāgen) — bære</div><div class=\"kurss-example\">Garten (garten) — hage</div><div class=\"kurss-example\">Vogel (få̄gel) — fugl</div><div class=\"kurss-example\">Segel (zēgel) — seil</div><div class=\"kurss-example\">Braten (brāten) — stek</div><div class=\"kurss-example\">Bogen (bå̄gen) — bue</div><div class=\"kurss-example\">Spiegel (sjpīgel) — speil</div><div class=\"kurss-example\">Finger (finger) — finger</div><div class=\"kurss-example\">Halter (halter) — holder</div><div class=\"kurss-example\">Arbeiter (arbaiter) — arbeider</div><div class=\"kurss-example\">Häuser (høyzer) — hus (flertall)</div><div class=\"kurss-example\">wieder (vīder) — igjen</div><div class=\"kurss-example\">breiter (braiter) — bredere</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Bokstaven h som lengdetegn</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rāmen) — ramme</div><div class=\"kurss-example\">Ohr (å̄r) — øre</div><div class=\"kurss-example\">Kohle (kå̄le) — kull</div><div class=\"kurss-example\">Zahl (tsāl) — tall</div><div class=\"kurss-example\">ihn (īn) — ham</div><div class=\"kurss-example\">ihm (īm) — ham / til ham</div><div class=\"kurss-example\">Huhn (hōn) — høne</div><div class=\"kurss-example\">nahm (nām) — tok</div><div class=\"kurss-example\">nehmen (nēmen) — ta</div><div class=\"kurss-example\">Schuh (sjō) — sko</div></div>\n              <p>I noen ord forlenger h den foregående vokalen. Da uttales h vanligvis ikke.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Endelser på e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lampe</div><div class=\"kurss-example\">Hase (hāze) — hare</div><div class=\"kurss-example\">Knabe (knābe) — gutt</div><div class=\"kurss-example\">Rabe (rābe) — ravn</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Lang i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dī) — artikkelen «die»</div><div class=\"kurss-example\">diese (dīze) — denne / disse</div><div class=\"kurss-example\">wieder (vīder) — igjen</div><div class=\"kurss-example\">Fliege (flīge) — flue</div><div class=\"kurss-example\">Ziege (tsīge) — geit</div><div class=\"kurss-example\">Stiel (sjtīl) — stilk / skaft</div><div class=\"kurss-example\">Dieb (dīp) — tyv</div><div class=\"kurss-example\">hier (hīr) — her</div></div>\n              <p>Lang i skrives ofte som ie på tysk.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Doble vokaler</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zāl) — sal</div><div class=\"kurss-example\">Saat (zāt) — såing / såkorn</div><div class=\"kurss-example\">Staat (sjtāt) — stat</div><div class=\"kurss-example\">Beere (bēre) — bær</div><div class=\"kurss-example\">See (zē) — innsjø / hav</div><div class=\"kurss-example\">Beet (bēt) — bed</div><div class=\"kurss-example\">Boot (bå̄t) — båt</div><div class=\"kurss-example\">Moor (må̄r) — myr</div><div class=\"kurss-example\">Moos (må̄s) — mose</div></div>\n              <p>Doble vokaler uttales vanligvis lange.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — vegg</div><div class=\"kurss-example\">Wände (vende) — vegger</div><div class=\"kurss-example\">Vater (fāter) — far</div><div class=\"kurss-example\">Väter (fǣter) — fedre</div><div class=\"kurss-example\">Schrank (sjrank) — skap</div><div class=\"kurss-example\">Schränke (sjrenke) — skap (flertall)</div><div class=\"kurss-example\">Bank (bank) — benk / bank</div><div class=\"kurss-example\">Bänke (benke) — benker</div><div class=\"kurss-example\">Tal (tāl) — dal</div><div class=\"kurss-example\">Täler (tǣler) — daler</div></div>\n              <p>ä er omlyd av a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rå̄ze) — rose</div><div class=\"kurss-example\">Röschen (rø̄s-kjen) — liten rose</div><div class=\"kurss-example\">Ofen (å̄fen) — ovn</div><div class=\"kurss-example\">Öfen (ø̄fen) — ovner</div><div class=\"kurss-example\">Rock (råkk) — skjørt</div><div class=\"kurss-example\">Röcke (røkke) — skjørt (flertall)</div></div>\n              <p>ö er omlyd av o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (korts) — kort</div><div class=\"kurss-example\">kürzer (kyrtser) — kortere</div><div class=\"kurss-example\">Kunst (konst) — kunst</div><div class=\"kurss-example\">Künste (kynste) — kunster</div><div class=\"kurss-example\">Mutter (motter) — mor</div><div class=\"kurss-example\">Mütter (mytter) — mødre</div></div>\n              <p>ü er omlyd av u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftonger: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — tre</div><div class=\"kurss-example\">Bäume (bøyme) — trær</div><div class=\"kurss-example\">Haus (haus) — hus</div><div class=\"kurss-example\">Häuser (høyzer) — hus (flertall)</div><div class=\"kurss-example\">Strauch (sjtraukh) — busk</div><div class=\"kurss-example\">Sträucher (sjtrøykjer) — busker</div><div class=\"kurss-example\">Maus (maus) — mus</div><div class=\"kurss-example\">Mäuse (møyze) — mus (flertall)</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftonger: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (høyte) — i dag</div><div class=\"kurss-example\">Leute (løyte) — folk</div><div class=\"kurss-example\">neu (nøy) — ny</div><div class=\"kurss-example\">neun (nøyn) — ni</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftonger: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — min</div><div class=\"kurss-example\">dein (dain) — din</div><div class=\"kurss-example\">sein (zain) — hans / dens / være</div><div class=\"kurss-example\">frei (frai) — fri</div><div class=\"kurss-example\">arbeiten (arbaiten) — arbeide</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Uttalenotater til 2. leksjon</h4>\n              <ul class=\"kurss-summary-list\"><li>i ordene ich, nicht, rechnen, zeichnen uttales «ch» bløtt, omtrent som norsk «kj»</li><li>i ordene arbeiten og zeichnen uttales «ei» som «ai»</li><li>«sp» i begynnelsen av et ord uttales som «sjp»</li><li>i verbet tun uttales «u» langt</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Oppsummering</h4>\n              <ul class=\"kurss-summary-list\"><li>én konsonant etter vokalen → ofte lang vokal</li><li>to eller flere konsonanter → ofte kort vokal</li><li>h kan forlenge vokalen</li><li>ie betyr ofte lang i</li><li>doble vokaler er vanligvis lange</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Konsonanter og bokstavkombinasjoner</h3>\n            <p class=\"kurss-lesson-intro\">På tysk uttales noen konsonanter og bokstavkombinasjoner annerledes enn de skrives. I denne leksjonen finner du de viktigste eksemplene for nybegynnere.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Konsonanter</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (das rāt) — hjul</div><div class=\"kurss-example\">die Räder (dī rǣder) — hjul (flertall)</div><div class=\"kurss-example\">Bad (bāt) — bad</div><div class=\"kurss-example\">Bäder (bǣder) — bad (flertall)</div></div>\n              <p>I slutten av et ord uttales konsonantene ofte ikke slik de skrives.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>«ch» kan uttales bløtt eller hardt. I noen ord ligner den norsk «kj» (som i «kjole»), i andre er den hardere, nærmere «k» – en hes lyd bak i halsen (her skrevet «kh»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rekjnen) — regne</div><div class=\"kurss-example\">zeichnen (tsaikjnen) — tegne</div><div class=\"kurss-example\">nicht (nikjt) — ikke</div><div class=\"kurss-example\">schlecht (sjlekjt) — dårlig</div><div class=\"kurss-example\">mich (mikj) — meg</div><div class=\"kurss-example\">dich (dikj) — deg</div><div class=\"kurss-example\">Strauch (sjtraukh) — busk</div><div class=\"kurss-example\">noch (nåkh) — ennå / fortsatt</div><div class=\"kurss-example\">Nacht (nakht) — natt</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>«sch» uttales på tysk som norsk «sj».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (sjōle) — skole</div><div class=\"kurss-example\">Schüler (sjȳler) — elev</div><div class=\"kurss-example\">Schiff (sjiff) — skip</div><div class=\"kurss-example\">Schraube (sjraube) — skrue</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp og st i begynnelsen av ord</h4>\n              <p>I begynnelsen av et ord eller en stavelse uttales «sp» ofte som «sjp» og «st» som «sjt».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (sjpīlen) — spille / leke</div><div class=\"kurss-example\">Sprung (sjprong) — hopp</div><div class=\"kurss-example\">stehen (sjtēen) — stå</div><div class=\"kurss-example\">Stall (sjtall) — stall / fjøs</div><div class=\"kurss-example\">Stand (sjtant) — stand / tilstand</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>«qu» uttales på tysk vanligvis som «kv».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvāl) — pine / kval</div><div class=\"kurss-example\">Quartier (kvartīr) — innkvartering / kvarter</div><div class=\"kurss-example\">quer (kvēr) — på tvers</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s og z</h4>\n              <p>I begynnelsen av et ord uttales «s» ofte som en stemt s, som engelsk «z». Bokstaven «z» uttales på tysk som «ts».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zāgen) — si</div><div class=\"kurss-example\">singen (zingen) — synge</div><div class=\"kurss-example\">Rose (rå̄ze) — rose</div><div class=\"kurss-example\">Zahl (tsāl) — tall</div><div class=\"kurss-example\">Zeit (tsait) — tid</div><div class=\"kurss-example\">Zink (tsink) — sink</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>På tysk uttales «v» ofte som «f». I fremmedord uttales den ofte som norsk «v».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fāter) — far</div><div class=\"kurss-example\">von (fån) — fra / av</div><div class=\"kurss-example\">viel (fīl) — mye</div><div class=\"kurss-example\">vier (fīr) — fire</div><div class=\"kurss-example\">Villa (villa) — villa</div><div class=\"kurss-example\">Klavier (klavīr) — piano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x og y</h4>\n              <p>«x» uttales som «ks». «y» uttales i noen ord som «ü» (omtrent som norsk «y»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fēliks) — Felix</div><div class=\"kurss-example\">Axt (akst) — øks</div><div class=\"kurss-example\">Mystik (mystik) — mystikk</div><div class=\"kurss-example\">Mythe (mȳte) — myte</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>«ß» uttales på tysk som «s».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fōs) — fot</div><div class=\"kurss-example\">Füße (fȳse) — føtter</div><div class=\"kurss-example\">Grüße (grȳse) — hilsener</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Oppsummering</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sj</li><li>sp / st i begynnelsen → sjp / sjt</li><li>qu → kv</li><li>z → ts</li><li>v ofte → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Grunnleggende om verb</h3>\n            <p class=\"kurss-lesson-intro\">Verb fra 1. leksjon og bøyningen deres (konjugasjon)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Verb</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — å komme</div><div class=\"kurss-example\">gehen — å gå</div><div class=\"kurss-example\">stehen — å stå</div><div class=\"kurss-example\">singen — å synge</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — jeg kommer</div><div class=\"kurss-example\">du kommst — du kommer</div><div class=\"kurss-example\">er kommt — han kommer</div><div class=\"kurss-example\">sie kommt — hun kommer</div><div class=\"kurss-example\">wir kommen — vi kommer</div><div class=\"kurss-example\">ihr kommt — dere kommer</div><div class=\"kurss-example\">sie kommen — de kommer</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — jeg går</div><div class=\"kurss-example\">du gehst — du går</div><div class=\"kurss-example\">er geht — han går</div><div class=\"kurss-example\">sie geht — hun går</div><div class=\"kurss-example\">wir gehen — vi går</div><div class=\"kurss-example\">ihr geht — dere går</div><div class=\"kurss-example\">sie gehen — de går</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — jeg står</div><div class=\"kurss-example\">du stehst — du står</div><div class=\"kurss-example\">er steht — han står</div><div class=\"kurss-example\">sie steht — hun står</div><div class=\"kurss-example\">wir stehen — vi står</div><div class=\"kurss-example\">ihr steht — dere står</div><div class=\"kurss-example\">sie stehen — de står</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — jeg synger</div><div class=\"kurss-example\">du singst — du synger</div><div class=\"kurss-example\">er singt — han synger</div><div class=\"kurss-example\">sie singt — hun synger</div><div class=\"kurss-example\">wir singen — vi synger</div><div class=\"kurss-example\">ihr singt — dere synger</div><div class=\"kurss-example\">sie singen — de synger</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Verb fra 2. leksjon</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — å spille</div><div class=\"kurss-example\">arbeiten — å arbeide</div><div class=\"kurss-example\">fragen — å spørre</div><div class=\"kurss-example\">antworten — å svare</div><div class=\"kurss-example\">rechnen — å regne</div><div class=\"kurss-example\">zeichnen — å tegne</div><div class=\"kurss-example\">tun — å gjøre</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — jeg spiller</div><div class=\"kurss-example\">du spielst — du spiller</div><div class=\"kurss-example\">er spielt — han spiller</div><div class=\"kurss-example\">sie spielt — hun spiller</div><div class=\"kurss-example\">wir spielen — vi spiller</div><div class=\"kurss-example\">ihr spielt — dere spiller</div><div class=\"kurss-example\">sie spielen — de spiller</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — jeg arbeider</div><div class=\"kurss-example\">du arbeitest — du arbeider</div><div class=\"kurss-example\">er arbeitet — han arbeider</div><div class=\"kurss-example\">sie arbeitet — hun arbeider</div><div class=\"kurss-example\">wir arbeiten — vi arbeider</div><div class=\"kurss-example\">ihr arbeitet — dere arbeider</div><div class=\"kurss-example\">sie arbeiten — de arbeider</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — jeg spør</div><div class=\"kurss-example\">du fragst — du spør</div><div class=\"kurss-example\">er fragt — han spør</div><div class=\"kurss-example\">sie fragt — hun spør</div><div class=\"kurss-example\">wir fragen — vi spør</div><div class=\"kurss-example\">ihr fragt — dere spør</div><div class=\"kurss-example\">sie fragen — de spør</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — jeg svarer</div><div class=\"kurss-example\">du antwortest — du svarer</div><div class=\"kurss-example\">er antwortet — han svarer</div><div class=\"kurss-example\">sie antwortet — hun svarer</div><div class=\"kurss-example\">wir antworten — vi svarer</div><div class=\"kurss-example\">ihr antwortet — dere svarer</div><div class=\"kurss-example\">sie antworten — de svarer</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — jeg regner</div><div class=\"kurss-example\">du rechnest — du regner</div><div class=\"kurss-example\">er rechnet — han regner</div><div class=\"kurss-example\">sie rechnet — hun regner</div><div class=\"kurss-example\">wir rechnen — vi regner</div><div class=\"kurss-example\">ihr rechnet — dere regner</div><div class=\"kurss-example\">sie rechnen — de regner</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — jeg tegner</div><div class=\"kurss-example\">du zeichnest — du tegner</div><div class=\"kurss-example\">er zeichnet — han tegner</div><div class=\"kurss-example\">sie zeichnet — hun tegner</div><div class=\"kurss-example\">wir zeichnen — vi tegner</div><div class=\"kurss-example\">ihr zeichnet — dere tegner</div><div class=\"kurss-example\">sie zeichnen — de tegner</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — jeg gjør</div><div class=\"kurss-example\">du tust — du gjør</div><div class=\"kurss-example\">er tut — han gjør</div><div class=\"kurss-example\">sie tut — hun gjør</div><div class=\"kurss-example\">wir tun — vi gjør</div><div class=\"kurss-example\">ihr tut — dere gjør</div><div class=\"kurss-example\">sie tun — de gjør</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Setningsoppbygning</h3>\n            <p class=\"kurss-lesson-intro\">I en spørresetning står verbet på tysk vanligvis på første plass.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Eksempler</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Du kommer.</div><div class=\"kurss-example\">Kommst du? — Kommer du?</div><div class=\"kurss-example\">Er singt. — Han synger.</div><div class=\"kurss-example\">Singt er? — Synger han?</div><div class=\"kurss-example\">Stehst du? — Står du?</div><div class=\"kurss-example\">Ja, ich stehe. — Ja, jeg står.</div><div class=\"kurss-example\">Geht ihr? — Går dere?</div><div class=\"kurss-example\">Ja, wir gehen. — Ja, vi går.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Spørsmål med «was»</h4>\n              <p>Hvis spørsmålet begynner med et spørreord, står verbet på tysk vanligvis rett etter spørreordet.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Hva gjør du?</div><div class=\"kurss-example\">Was tut er? — Hva gjør han?</div><div class=\"kurss-example\">Was tut sie? — Hva gjør hun?</div><div class=\"kurss-example\">Was tun sie? — Hva gjør de?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Nektelse med «nicht»</h4>\n              <p>Hvis nektelsen «nicht» gjelder verbet, står den på tysk vanligvis etter verbet.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Jeg spiller ikke.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul spør ikke.</div><div class=\"kurss-example\">Er kommt nicht. — Han kommer ikke.</div><div class=\"kurss-example\">Sie singen nicht. — De synger ikke.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Setninger fra leksjon 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Spiller du?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Nei, jeg spiller ikke, jeg arbeider.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul spør ikke, han arbeider.</div><div class=\"kurss-example\">Arbeitest du? — Arbeider du?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Nei, jeg arbeider ikke, jeg synger.</div><div class=\"kurss-example\">Was tut Paul? — Hva gjør Paul?</div><div class=\"kurss-example\">Er spielt. — Han spiller.</div><div class=\"kurss-example\">Was tut Marie? — Hva gjør Marie?</div><div class=\"kurss-example\">Sie singt. — Hun synger.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul spiller, men Marie synger.</div><div class=\"kurss-example\">Singt ihr? — Synger dere?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Nei, vi synger ikke, vi arbeider.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Hva gjør Paul og Marie?</div><div class=\"kurss-example\">Sie fragen. — De spør.</div><div class=\"kurss-example\">Sie antworten nicht. — De svarer ikke.</div><div class=\"kurss-example\">Wer arbeitet? — Hvem arbeider?</div><div class=\"kurss-example\">Wir arbeiten. — Vi arbeider.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Vi regner og tegner.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — De kommer, spør, svarer, arbeider, spiller, synger og går.</div></div>\n            </section>",
  "kurssLesson1": "            <h3>Leksjon 1</h3>\n            <p class=\"kurss-lesson-intro\">Første leksjon: verb i presens, gloser, uttale, grammatikk og oversettelse.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verb i presens</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Verbene og bøyningen deres i presens.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — å komme</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>jeg kommer</span><span>du</span><strong>kommst</strong><span>du kommer</span><span>er / sie</span><strong>kommt</strong><span>han / hun kommer</span><span>wir</span><strong>kommen</strong><span>vi kommer</span><span>ihr</span><strong>kommt</strong><span>dere kommer</span><span>sie / Sie</span><strong>kommen</strong><span>de / De kommer</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — å gå</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>jeg går</span><span>du</span><strong>gehst</strong><span>du går</span><span>er / sie</span><strong>geht</strong><span>han / hun går</span><span>wir</span><strong>gehen</strong><span>vi går</span><span>ihr</span><strong>geht</strong><span>dere går</span><span>sie / Sie</span><strong>gehen</strong><span>de / De går</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — å stå</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>jeg står</span><span>du</span><strong>stehst</strong><span>du står</span><span>er / sie</span><strong>steht</strong><span>han / hun står</span><span>wir</span><strong>stehen</strong><span>vi står</span><span>ihr</span><strong>steht</strong><span>dere står</span><span>sie / Sie</span><strong>stehen</strong><span>de / De står</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — å synge</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>jeg synger</span><span>du</span><strong>singst</strong><span>du synger</span><span>er / sie</span><strong>singt</strong><span>han / hun synger</span><span>wir</span><strong>singen</strong><span>vi synger</span><span>ihr</span><strong>singt</strong><span>dere synger</span><span>sie / Sie</span><strong>singen</strong><span>de / De synger</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Eksempler</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Gloser</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Omtrentlig uttale av ordene er gitt i parentes med norske bokstaver.<br>Dette gjelder også i de neste leksjonene.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vir) — vi</div><div class=\"kurss-example\">I ordet «wir» uttales bokstaven i langt.</div><div class=\"kurss-example\">kommen (kommen) — å komme</div><div class=\"kurss-example\">gehen (ge-en) — å gå</div><div class=\"kurss-example\">stehen (sjte-en) — å stå</div><div class=\"kurss-example\">singen (zingen) — å synge</div><div class=\"kurss-example\">du (du) kommst — du kommer</div><div class=\"kurss-example\">er (er) kommt — han kommer</div><div class=\"kurss-example\">sie (zi) kommt — hun kommer</div><div class=\"kurss-example\">wer (ver) — hvem?</div><div class=\"kurss-example\">ja (ja) — ja</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Riktig uttale av ordene, skrevet med norske bokstaver, er gitt i leksjonene.</div><div class=\"kurss-example\">Wir (vir) — vi. I ordet wir uttales i alltid langt.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiv</h4><div class=\"lesson1-grammar-note\">Verbets grunnform. Infinitiv ender vanligvis på -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Presensendelser</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Fjern <span class=\"lesson1-ending-accent\">-en</span> fra verbets grunnform og legg til endelsen.</strong></p><p>Eksempel: kommen → komm + endelse</p><div class=\"lesson1-ending-process\" aria-label=\"Slik dannes presensformene\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>grunnform</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>fjern <span class=\"lesson1-ending-accent\">-en</span></strong><span>stammen blir igjen</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>stamme</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>legg til endelse</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Eksempler</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Spørresetninger</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>I en tysk spørresetning flyttes verbet vanligvis til første plass.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På norsk:<br>Du kommer.<br>Kommer du?</div><div class=\"kurss-example\">På tysk:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — du kommer<br>kommst du? — kommer du?</div><div class=\"kurss-example\">er singt — han synger<br>singt er? — synger han?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Forskjell i person</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — han kommer</div><div class=\"kurss-example\">sie kommt — hun kommer</div><div class=\"kurss-example\">sie kommen — de kommer</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversett</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 1 treningskort\">\n                    <span class=\"lesson1-training-progress\">Leksjon 1 · Oversett: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Kommer du?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klikk på kortet for å se den tyske oversettelsen. Etter svaret viser neste klikk neste kort.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson2": "            <h3>Leksjon 2</h3>\n            <p class=\"kurss-lesson-intro\">Andre leksjon: dialoger, ord, uttale, grammatikk og oversettelse.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / setninger</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — å leke; å spille</div>\n                  <div class=\"kurss-example\">nein — nei</div>\n                  <div class=\"kurss-example\">nicht — ikke</div>\n                  <div class=\"kurss-example\">arbeiten — å arbeide</div>\n                  <div class=\"kurss-example\">fragen — å spørre</div>\n                  <div class=\"kurss-example\">was tut er? — hva gjør han?</div>\n                  <div class=\"kurss-example\">was tun sie? — hva gjør de?</div>\n                  <div class=\"kurss-example\">aber — men</div>\n                  <div class=\"kurss-example\">antworten — å svare</div>\n                  <div class=\"kurss-example\">rechnen — å regne</div>\n                  <div class=\"kurss-example\">zeichnen — å tegne</div>\n                  <div class=\"kurss-example\">Marie — Maria</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I ordene ich, nicht, rechnen, zeichnen uttales lyden ch mykt, omtrent som kj-lyden i norske ord som kjøre, kjenne.</div><div class=\"kurss-example\">I ordene arbeiten, zeichnen uttales diftongen ei omtrent som norsk ei i ord som hei, vei.</div><div class=\"kurss-example\">Konsonantforbindelsen sp uttales som sjp: spielen (sjpilen).</div><div class=\"kurss-example\">I verbet tun uttales u langt i alle personer.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Endelser med e</h4>\n                  <div class=\"lesson1-grammar-note\">Hvis verbstammen ender på t, d, chn, står det en e foran endelsene -st og -t ved bøyning.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Spørreord</h4>\n                  <div class=\"lesson1-grammar-note\">I spørresetninger som begynner med et spørreord, for eksempel: hva? hvem? hvilken? hvorfor? av hvilken grunn? osv., står verbet rett etter spørreordet.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Hva gjør du?</div><div class=\"kurss-example\">Was tut er? — Hva gjør han?</div><div class=\"kurss-example\">Was tut sie? — Hva gjør hun?</div><div class=\"kurss-example\">Was tun sie? — Hva gjør de?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Nektelse med nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Hvis nektelsen nicht gjelder verbet, står den etter verbet.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Han kommer ikke.</div><div class=\"kurss-example\">Sie singen nicht. — De synger ikke.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversett</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 2 oversettelseskort\">\n                    <span class=\"lesson1-training-progress\">Leksjon 2 · Oversett: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Hvem spør?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klikk på kortet for å se den tyske oversettelsen. Etter svaret viser neste klikk neste kort.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson3": "            <h3>Leksjon 3</h3>\n            <p class=\"kurss-lesson-intro\">Tredje leksjon: dialoger, ord, uttale, grammatikk og oversettelse.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / setninger</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — hvem</div><div class=\"kurss-example\">was — hva</div><div class=\"kurss-example\">hier — her</div><div class=\"kurss-example\">dort — der</div><div class=\"kurss-example\">der Tisch — bordet</div><div class=\"kurss-example\">ein Tisch — et bord</div><div class=\"kurss-example\">die Bank — benken</div><div class=\"kurss-example\">eine Bank — en benk</div><div class=\"kurss-example\">liegen — å ligge</div><div class=\"kurss-example\">liegt hier ein Buch? — er det / ligger det en bok her?</div><div class=\"kurss-example\">das Buch — boken</div><div class=\"kurss-example\">ein Buch — en bok</div><div class=\"kurss-example\">hängen — å henge</div><div class=\"kurss-example\">das Bild — bildet</div><div class=\"kurss-example\">ein Bild — et bilde</div><div class=\"kurss-example\">die Tafel — tavlen</div><div class=\"kurss-example\">eine Tafel — en tavle</div><div class=\"kurss-example\">wie — hvordan</div><div class=\"kurss-example\">ist — er</div><div class=\"kurss-example\">dick — tykk</div><div class=\"kurss-example\">das Heft — skriveboken</div><div class=\"kurss-example\">ein Heft — en skrivebok</div><div class=\"kurss-example\">dünn — tynn</div><div class=\"kurss-example\">niedrig — lav</div><div class=\"kurss-example\">hoch — høy</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Den lange i-lyden skrives på tysk med ie: liegen (ligen), hier (hir), wie (vi).</div><div class=\"kurss-example\">ck er en dobbel k: dick (dikk).</div><div class=\"kurss-example\">I adjektiver og adverb uttales endelsen -ig som en lett -ich: niedrig (nidrikj).</div><div class=\"kurss-example\">Hvis -ig etterfølges av e: -ige, uttales g som en tydelig g-lyd: niedrige (nidrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Subjekt</h4><div class=\"lesson1-grammar-note\">På tysk svarer subjektet på spørsmålet wer? / was? og står i nominativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Med wer? spør man etter personer.</div><div class=\"kurss-example\">Med was? spør man etter ting.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artikler</h4><div class=\"lesson1-grammar-note\">På tysk har substantivene 3 kjønn: hankjønn, hunkjønn og intetkjønn. Foran substantivet står vanligvis et lite ord som kalles artikkel. Dette ordet oversettes ikke.</div><h5 class=\"lesson2-subtitle\">Bestemt artikkel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hankjønn — der</div><div class=\"kurss-example\">hunkjønn — die</div><div class=\"kurss-example\">intetkjønn — das</div><div class=\"kurss-example\">I flertall er den bestemte artikkelen die for alle tre kjønn.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Ubestemt artikkel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hankjønn — ein</div><div class=\"kurss-example\">hunkjønn — eine</div><div class=\"kurss-example\">intetkjønn — ein</div><div class=\"kurss-example\">Den ubestemte artikkelen har ikke flertall.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Egennavn</h4><div class=\"lesson1-grammar-note\">Foran egennavn brukes ikke artikkel.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbets plass</h4><div class=\"lesson1-grammar-note\">I en fortellende setning står verbet på andre plass.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På tysk sier man om ting som står loddrett, at de står:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Om ting som ligger vannrett, sier man at de ligger:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Ting kan også henge:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversett</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 3 oversettelseskort\"><span class=\"lesson1-training-progress\">Leksjon 3 · Oversett: 1 / 22</span><span class=\"lesson1-training-text\">Regner du?</span></button><p class=\"lesson1-training-hint\">Klikk på kortet for å se den tyske oversettelsen. Etter svaret viser neste klikk neste kort.</p></div></div></details>",
  "kurssLesson4": "            <h3>Leksjon 4</h3>\n            <p class=\"kurss-lesson-intro\">Akkusativ, nehmen, hinlegen, hinausgehen og adjektiver.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / setninger</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nemen) — å ta</div><div class=\"kurss-example\">er nimmt (nimt) — han tar</div><div class=\"kurss-example\">der Federhalter (der federhalter) — penneskaftet</div><div class=\"kurss-example\">einen Federhalter — et penneskaft</div><div class=\"kurss-example\">zeigen — å vise</div><div class=\"kurss-example\">schwarz (sjvarts) — svart</div><div class=\"kurss-example\">weiß (veis) — hvit</div><div class=\"kurss-example\">die Feder (di feder) — pennen</div><div class=\"kurss-example\">eine Feder — en penn</div><div class=\"kurss-example\">spitz (sjpits) — spiss</div><div class=\"kurss-example\">hinlegen — å legge fra seg</div><div class=\"kurss-example\">legt hin — legger fra seg</div><div class=\"kurss-example\">das Mädchen (mætkjen) — jente</div><div class=\"kurss-example\">das Messer — kniven</div><div class=\"kurss-example\">ein Messer — en kniv</div><div class=\"kurss-example\">scharf — skarp</div><div class=\"kurss-example\">stumpf (sjtumpf) — sløv, butt</div><div class=\"kurss-example\">dann — så, deretter</div><div class=\"kurss-example\">hinaus — ut</div><div class=\"kurss-example\">hinausgehen — å gå ut</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Endelsene -en, -er, -el er trykklette, derfor høres e i disse endelsene bare svakt: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">På tysk kan h være både en lyd og et lengdetegn for vokalen foran.</div><div class=\"kurss-example\">Når h er lengdetegn, uttales den ikke som lyd: nehmen (nemen).</div><div class=\"kurss-example\">Når en vokal etterfølges av bare én konsonant, uttales vokalen langt: die (di) Feder (feder), den (den).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akkusativ</h4><div class=\"lesson1-grammar-note\">I hunkjønn og intetkjønn er akkusativ lik nominativ. Bare hankjønn endres.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronomen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — hankjønn</div><div class=\"kurss-example\">sie — hunkjønn</div><div class=\"kurss-example\">es — intetkjønn</div><div class=\"kurss-example\">i flertall — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Delbare verb</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjektiver</h4><div class=\"lesson1-grammar-note\">Når adjektivet er predikativ i setningen, bøyes det verken i kjønn eller tall.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Nektelse med nicht</h4><div class=\"lesson1-grammar-note\">Når nicht nekter et adjektiv, står det foran ordet som nektes.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Substantiver med endelsen -chen og -lein er intetkjønn: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversett</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 4 oversettelseskort\"><span class=\"lesson1-training-progress\">Leksjon 4 · Oversett: 1 / 16</span><span class=\"lesson1-training-text\">Jenta tar et penneskaft.</span></button><p class=\"lesson1-training-hint\">Klikk på kortet for å se den tyske oversettelsen. Etter svaret viser neste klikk neste kort.</p></div></div></details>",
  "kurssLesson5": "\n    <h3>Leksjon 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akkusativ, sitzen, fragen og endelsen -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / setninger</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zitsen) — å sitte</div>\n        <div class=\"kurss-example\">fragen (fragen) — å spørre</div>\n        <div class=\"kurss-example\">der Lehrer (der lerer) — lærer</div>\n        <div class=\"kurss-example\">gut (gut) — godt, bra</div>\n        <div class=\"kurss-example\">wen (ven) — hvem</div>\n        <div class=\"kurss-example\">loben — å rose</div>\n        <div class=\"kurss-example\">der Schüler (sjyler) — elev</div>\n        <div class=\"kurss-example\">klein — liten</div>\n        <div class=\"kurss-example\">groß (grås) — stor</div>\n        <div class=\"kurss-example\">die Lehrerin — lærerinne</div>\n        <div class=\"kurss-example\">die Schülerin — skolejente</div>\n        <div class=\"kurss-example\">schlecht (sjlekjt) — dårlig</div>\n        <div class=\"kurss-example\">tadeln — å irettesette</div>\n        <div class=\"kurss-example\">oder (åder) — eller</div>\n        <div class=\"kurss-example\">das Kind (kint) — barn</div>\n        <div class=\"kurss-example\">artig (artikj) — snill, lydig</div>\n        <div class=\"kurss-example\">die Mutter — mor</div>\n        <div class=\"kurss-example\">lieben (liben) — å elske</div>\n        <div class=\"kurss-example\">der Vater (fater) — far</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz er en doblet z og uttales som tysk z, altså ts: sitzen (zitsen).</div>\n        <div class=\"kurss-example\">I tyske ord uttales v som f: der Vater (fater).</div>\n        <div class=\"kurss-example\">ß kalles ess-tsett og uttales som norsk s: groß (grås), weiß (veis).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativ og akkusativ</h4><div class=\"lesson1-grammar-note\">På norsk har substantivene ingen egne kasusformer: subjektet svarer på spørsmålet hvem eller hva som gjør noe, og direkte objekt på spørsmålet hvem eller hva handlingen rettes mot.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På tysk er spørsmålet i nominativ wer? for personer og was? for ting.</div><div class=\"kurss-example\">I akkusativ er spørsmålet wen? for personer og was? for ting.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Artiklene i akkusativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akkusativ</h4><div class=\"lesson1-grammar-note\">Verbet fragen styrer akkusativ på tysk.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Endelsen -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Mange hunkjønnsord dannes med endelsen -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Verbets plass</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I en fortellende setning står verbet på andre plass.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversett</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 5 oversettelseskort\"><span class=\"lesson1-training-progress\">Leksjon 5 · Oversett: 1 / 16</span><span class=\"lesson1-training-text\">Hvem elsker faren?</span></button><p class=\"lesson1-training-hint\">Klikk på kortet for å se den tyske oversettelsen. Etter svaret viser neste klikk neste kort.</p></div></div>\n    </details>\n  ",
  "kurssLesson6": "\n    <h3>Leksjon 6</h3>\n    <p class=\"kurss-lesson-intro\">Tall, flertall, omlyd og flertallsformer av substantiver.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / setninger</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — befinner seg, er, ligger</div><div class=\"kurss-example\">der Bleistift (bleisjtift) — blyant</div><div class=\"kurss-example\">einige (einige) — noen</div><div class=\"kurss-example\">hinlegen — å legge fra seg</div><div class=\"kurss-example\">legt hin — legger fra seg</div><div class=\"kurss-example\">wieder (vider) — igjen</div><div class=\"kurss-example\">aufmachen — å åpne</div><div class=\"kurss-example\">er macht auf — han åpner</div><div class=\"kurss-example\">anspitzen (ansjpitsen) — å spisse</div><div class=\"kurss-example\">er spitzt an — han spisser</div><div class=\"kurss-example\">sich setzen — å sette seg</div><div class=\"kurss-example\">setzt sich — setter seg</div><div class=\"kurss-example\">der Schlüssel (sjlysel) — nøkkel</div><div class=\"kurss-example\">das Fenster (fenster) — vindu</div><div class=\"kurss-example\">die Tafel (di tafel) — tavle</div><div class=\"kurss-example\">der Garten — hage</div><div class=\"kurss-example\">der Löffel — skje</div><div class=\"kurss-example\">zählen (tselen) — å telle</div><div class=\"kurss-example\">die Nadel — nål</div><div class=\"kurss-example\">was ist das — hva er det?</div><div class=\"kurss-example\">der Hammer — hammer</div><div class=\"kurss-example\">die Hämmer — hamrer</div><div class=\"kurss-example\">der Deckel (der dekel) — lokk</div><div class=\"kurss-example\">der Teller — tallerken</div><div class=\"kurss-example\">der Wagen — vogn</div><div class=\"kurss-example\">der Schlitten — slede, kjelke</div><div class=\"kurss-example\">das Ding — tingen</div><div class=\"kurss-example\">die Dinge — tingene</div><div class=\"kurss-example\">wie sind die Dinge? — hvordan er tingene?</div><div class=\"kurss-example\">voll (fåll) — full</div><div class=\"kurss-example\">leer (ler) — tom</div><div class=\"kurss-example\">schwer (sjver) — tung, vanskelig</div><div class=\"kurss-example\">leicht — lett</div><div class=\"kurss-example\">der Eimer — bøtte</div><div class=\"kurss-example\">wieviel (vifil) — hvor mye, hvor mange</div><div class=\"kurss-example\">wieviel Nadeln — hvor mange nåler</div><div class=\"kurss-example\">hier (hir) — her</div><div class=\"kurss-example\">dort — der</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä er omlyd av vokalen a og uttales som kort eller lang lukket e.</div><div class=\"kurss-example\">Eksempler: das Mädchen (mætkjen), die Bänke (di benke), der Vater (der fater), die Väter (di fæter).</div><div class=\"kurss-example\">ü er omlyd av vokalen u. Når du uttaler den, skal leppene rundes kraftig mens du prøver å si i – omtrent som norsk y.</div><div class=\"kurss-example\">Eksempler: fünf, der Schlüssel (sjlysel).</div><div class=\"kurss-example\">ö uttales med runde lepper mens man prøver å si e – omtrent som norsk ø: der Löffel.</div><div class=\"kurss-example\">Dobbel vokal betegner lang vokal: leer (ler).</div><div class=\"kurss-example\">Diftongen eu uttales omtrent som norsk øy: neun (nøyn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammatikk og forklaringer</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Det trykksterke prefikset i et sammensatt verb skilles i presens fra verbet og står sist i setningen.</div><div class=\"kurss-example\">Eksempler: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Tallordet én har former i alle tre kjønn når det brukes sammen med et substantiv: i hankjønn ein, i hunkjønn eine, i intetkjønn ein.</div><div class=\"kurss-example\">Eksempler: ein Schüler — én elev; eine Schülerin — én skolejente; ein Kind — ett barn.</div><div class=\"kurss-example\">Tall: eins, zwei, drei, vier (fir), fünf, sechs (zeks), sieben (ziben), acht, neun (nøyn), zehn (tsen).</div><div class=\"kurss-example\">Kopulaverbet har på tysk en entallsform og en flertallsform: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Det påpekende pronomenet det endres ikke på norsk i setninger som «det er …», og på tysk brukes også bare én form: das.</div><div class=\"kurss-example\">Eksempler: det er en hammer — das ist ein Hammer; det er en nål — das ist eine Nadel; det er hamrer — das sind Hämmer; det er nåler — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — vogn og der Schlitten — slede brukes på tysk både i entall og i flertall.</div><div class=\"kurss-example\">Hankjønns- og intetkjønnsord med endelsen -er, -el, -en får ofte ingen endelse i flertall.</div><div class=\"kurss-example\">Eksempler: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Hunkjønnsord med endelsen -el, -er får -n i flertall.</div><div class=\"kurss-example\">Eksempler: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Unntak: die Mutter (mor) — die Mütter (mødre); die Tochter (datter) — die Töchter (døtre).</div><div class=\"kurss-example\">Den ubestemte artikkelen har ikke flertall: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">I en fortellende setning står verbet på andre plass: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Oversett</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 6 oversettelseskort\"><span class=\"lesson1-training-progress\">Leksjon 6 · Oversett: 1 / 21</span><span class=\"lesson1-training-text\">Paul tar en blyant og tegner.</span></button><p class=\"lesson1-training-hint\">Klikk på kortet for å se den tyske oversettelsen. Etter svaret viser neste klikk neste kort.</p></div></div>\n    </details>\n  ",
  "kurssLesson7": "            <h3>Leksjon 7</h3>\n            <p class=\"kurss-lesson-intro\">Sjuende leksjon: imperativ, tiltaleform og flertall.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / setninger</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — å synge</div><div class=\"kurss-example\">singe — syng</div><div class=\"kurss-example\">singt — syng</div><div class=\"kurss-example\">singen Sie — syng</div><div class=\"kurss-example\">das Lied (das lit) — sang</div><div class=\"kurss-example\">Sie — De</div><div class=\"kurss-example\">zählen — å telle</div><div class=\"kurss-example\">das Fräulein (frøylein) — frøken</div><div class=\"kurss-example\">der Müller — møller</div><div class=\"kurss-example\">öffnen — å åpne</div><div class=\"kurss-example\">das Fenster (fenster) — vindu</div><div class=\"kurss-example\">alle — alle</div><div class=\"kurss-example\">der Spiegel (sjpigel) — speil</div><div class=\"kurss-example\">der Lappen — fille, klut</div><div class=\"kurss-example\">der Spaten — spade</div><div class=\"kurss-example\">der Besen — kost</div><div class=\"kurss-example\">die Schaufel — skuffe</div><div class=\"kurss-example\">die Schüssel — bolle</div><div class=\"kurss-example\">das Zimmer — rom</div><div class=\"kurss-example\">das Ufer (ufer) — bredd</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttale</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp i begynnelsen av et ord eller en stavelse uttales som sjp: der Spiegel (der sjpigel).</div><div class=\"kurss-example\">sch uttales som norsk sj: die Schaufel (di sjaufel), die Schüssel (di sjysel).</div><div class=\"kurss-example\">Diftongen äu uttales omtrent som norsk øy: das Fräulein (das frøylein).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatikk</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Imperativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Imperativ i 2. person entall tilsvarer verbets 2. person entall uten personendelsen -st, med endelsen -e lagt til.</div><div class=\"kurss-example\">Eksempler: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Svært ofte brukes ikke endelsen -e når imperativformen uten den blir enstavelses: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Imperativ i flertall</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Imperativformen i 2. person flertall er lik 2. person flertall i presens, men brukes uten pronomen.</div><div class=\"kurss-example\">Eksempler: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Høflig tiltale med Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Høflig tiltale, som tilsvarer norsk «De», er lik 3. person flertall. Pronomenet Sie skrives med stor forbokstav og står etter verbet.</div><div class=\"kurss-example\">Eksempler: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Verbet öffnen får for lettere uttales skyld en e mellom stammen og endelsen i 2. og 3. person entall og i 2. person flertall: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Øvelse</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Leksjon 7 øvelseskort\"><span class=\"lesson1-training-progress\">Leksjon 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — å spørre</span></button><p class=\"lesson1-training-hint\">Trykk på kortet for å se imperativformene.</p></div></div></details>"
};

